 (OUT/'serialization_recovery_53.json').write_text(json.dumps(recovery,indent=2))
 # Actual actuator mapping is recorded, not a novel model stiffness.
 unitree=Path('IsaacLab/source/isaaclab_assets/isaaclab_assets/robots/unitree.py');full=Path('sitting_task/src/humanoid_sitting/tasks/full_transition.py');assert 'self.scene.robot.actuators[\'feet\'].stiffness=160.' in full.read_text()
 stiffness=dict(leg_order=['hip_pitch','hip_roll','hip_yaw','knee','ankle_pitch','ankle_roll'],stiffness_Nm_per_rad=[200,150,150,200,160,160],source_sha256={str(p):sha(p) for p in [unitree,full]},scope='Existing G1 leg stiffness plus existing FullTransition feet override. Offline vertical-force feedforward is an approximation; no runtime value changed.')
 (OUT/'stiffness_sources.json').write_text(json.dumps(stiffness,indent=2))
 cases=[0,2,6,10];labels=['36 cm / +15°','36 cm / +20°','37 cm / +16.25°','36.5 cm / +17.5°'];f=[next(r for r in a['rows'] if r['case']==c and r['assumption']=='foot_only_before_contact')['best_other_screens_feasible']['clearance_m']*1000 for c in cases];s=[next(r for r in a['rows'] if r['case']==c and r['assumption']=='hypothetical_seat_supported_endpoint')['best_other_screens_feasible']['clearance_m']*1000 for c in cases]
 fig,axes=plt.subplots(1,2,figsize=(13.5,5.1));x=np.arange(4);axes[0].bar(x-.18,f,.36,label='Foot-only endpoint');axes[0].bar(x+.18,s,.36,label='Assumed seat-supported endpoint',color='#d48d35');axes[0].axhline(3,color='#b63c3c',ls='--',label='3 mm model screen');axes[0].set_xticks(x,labels,rotation=15);axes[0].set_ylabel('Forbidden-body clearance (mm)');axes[0].set_title('60 mm hypothetical rearward stance shift');axes[0].legend(fontsize=8)
 duration=[r['necessary_command_seconds_with_initial_jump_at015'] for r in audit['steps']];axes[1].bar(['60 mm','100 mm'],duration,color='#b63c3c');axes[1].axhline(14,color='black',ls='--',label='1–15 s available, including sitting');axes[1].set_ylabel('Necessary seconds at 0.15 rad/s');axes[1].set_title('Tested stepping paths alone exceed the window');axes[1].legend(fontsize=8)
 for i,v in enumerate(duration):axes[1].text(i,v+.15,f'{v:.2f} s',ha='center')
 axes[1].set_ylim(0,23);fig.suptitle('OFFLINE MODELS ONLY — repair unresolved; no physical trial / PPO / holdout',fontsize=13);fig.tight_layout();fig.savefig(OUT/'comparison.png',dpi=155);plt.close(fig)
 fig,axes=plt.subplots(2,2,figsize=(13,8));pathdiag=[]
